 Impl(fs::path directory,const std::string& type):root(fs::weakly_canonical(std::move(directory))){auto args=parameters(type);require(args[""]=="multipart/form-data"&&args.contains("boundary"),400,"Expected multipart/form-data upload");boundary=args["boundary"];require(!boundary.empty()&&boundary.size()<=70&&boundary.find_first_of("\r\n\0",0,3)==std::string::npos,400,"Invalid multipart boundary");require(!root.empty()&&root.is_absolute(),400,"Native media directory required");}
