 void headers(const std::string& value){std::map<std::string,std::string> fields;std::istringstream lines(value);std::string line;while(std::getline(lines,line)){auto colon=line.find(':');require(colon!=std::string::npos,400,"Invalid multipart header");auto key=lower(trim(line.substr(0,colon)));require(!fields.contains(key),400,"Duplicate multipart header");fields[key]=trim(line.substr(colon+1));}require(fields.contains("content-disposition"),400,"Missing multipart disposition");auto disposition=parameters(fields["content-disposition"]);require(disposition[""]=="form-data",400,"Expected form-data disposition");inFile=false;if(selected||!(disposition["name"]=="video"||disposition["name"]=="file"))return;auto file=disposition["filename"];if(disposition.contains("filename*")){auto value=disposition["filename*"];auto marker=value.find("''");require(marker!=std::string::npos&&lower(value.substr(0,marker))=="utf-8",400,"Unsupported upload filename encoding");file=value.substr(marker+2);}require(!file.empty(),400,"Choose a media file to upload");if(fields.contains("content-transfer-encoding"))require(lower(fields["content-transfer-encoding"])=="binary"||lower(fields["content-transfer-encoding"])=="8bit",400,"Unsupported upload transfer encoding");name=filename(file);fs::create_directories(root);std::string pattern=(root/".upload-XXXXXX.part").string();std::vector<char> writable(pattern.begin(),pattern.end());writable.push_back(0);fd=mkstemps(writable.data(),5);if(fd<0)throw ApiError(500,"The media could not be saved");temporary=writable.data();selected=true;inFile=true;}
