public:
 AssetSession(beast::tcp_stream&& stream,http::request<http::string_body>&& request,MediaHttpAsset asset,asio::thread_pool& workers,std::function<void()> finished):stream_(std::move(stream)),request_(std::move(request)),asset_(std::move(asset)),workers_(workers),finished_(std::move(finished)){}
