void serveMediaUpload(beast::tcp_stream&& stream,beast::flat_buffer&& buffer,http::request_parser<http::string_body>&& parser,const fs::path& root,asio::thread_pool& workers,std::function<void()> finished){std::make_shared<UploadSession>(std::move(stream),std::move(buffer),std::move(parser),root,workers,std::move(finished))->run();}
void serveMediaAsset(beast::tcp_stream&& stream,http::request<http::string_body>&& request,MediaHttpAsset asset,asio::thread_pool& workers,std::function<void()> finished){std::make_shared<AssetSession>(std::move(stream),std::move(request),std::move(asset),workers,std::move(finished))->run();}
